import { type TreeMapLeafNode } from './treemap.js';
import { ColorToken } from '../../core/types/color-palette.js';
export interface InternalTreeMapLeafNode extends TreeMapLeafNode {
    color?: ColorToken;
    highlighted?: boolean;
}
export interface InternalTreeMapClusterNode extends InternalTreeMapLeafNode {
    children?: Array<InternalTreeMapLeafNode>;
}
export interface InternalTreeMapRootNode {
    children: Array<InternalTreeMapClusterNode>;
    value: number;
    name?: string;
}
export interface InternalTreeMapDataEntryMeta extends InternalTreeMapLeafNode {
    id: string;
}
export interface TreeMapMetadata {
    metadataSeries: TreeMapLeafNode[];
    metadataMap: WeakMap<TreeMapLeafNode, InternalTreeMapDataEntryMeta>;
}
export interface InternalTreeMapData {
    tree: InternalTreeMapRootNode;
    unit?: string;
}
export interface TreeMapSlots {
    tooltip?: boolean;
}
export interface TreeMapCSVEntry extends TreeMapLeafNode {
    parent: string;
}
